//! Principal component analysis against Origin's `pca` X-Function (Origin 2016). Inputs are generated by us
//! (five columns, twelve rows, three missing numbers). The runs are `tools/origin-ref/pca-*.lines.txt` and the
//! raw outputs are kept in `re-workspace/scratch/t29/` (local). Signs of the eigenvectors follow Origin's rule
//! (sum of the components positive). Tolerance 1e-5 relative for eigenvalues, loadings and scores (Origin prints
//! 17 digits for most cells but reports the eigenvalues and the equality test statistics with six).

use sheaf_calc::{PcaOptions, pca};

const NAN: f64 = f64::NAN;

fn data() -> Vec<Vec<f64>> {
    vec![
        vec![24.96, 24.56, 21.98, 19.92, 20.41, 23.33, 26.83, 28.88, 28.81, 27.47, 26.43, 26.76],
        vec![19.98, 13.09, 18.49, NAN, 13.52, 12.37, 15.28, 14.46, 10.99, 8.81, 11.11, 12.28],
        vec![13.91, 22.27, 18.83, 15.97, 19.45, 18.25, 13.03, 21.25, 12.76, 15.28, 18.33, 10.46],
        vec![19.32, 20.56, 23.15, 20.71, 25.23, 27.66, 27.77, NAN, NAN, 37.79, 43.74, 42.51],
        vec![23.18, 14.92, 20.26, 17.06, 22.9, 16.22, 18.24, 14.26, 20.21, 17.22, 18.31, 13.09],
    ]
}


#[test]
fn corr_listwise() {
    let a = pca(&data(), &PcaOptions { correlation: true, pairwise: false, components: 5, standardize_scores: false }).unwrap();
    check(&a.count.iter().map(|&n| n as f64).collect::<Vec<_>>(), &[9.0, 9.0, 9.0, 9.0, 9.0], 0.0, "N");
    check(&a.missing.iter().map(|&n| n as f64).collect::<Vec<_>>(), &[0.0, 1.0, 0.0, 2.0, 0.0], 0.0, "missing");
    check(&a.mean, &[24.747777777777777, 13.88111111111111, 16.645555555555553, 29.747777777777774, 18.26], 1e-12, "mean");
    check(&a.sd, &[2.428794854335056, 3.524799442679131, 3.7142297691146915, 9.278329291658304, 3.407099206069585], 1e-12, "sd");
    check(&a.eigenvalues, &[2.815567, 1.22519, 0.5367, 0.28535, 0.137193], 1e-5, "eigenvalues");
    check(&a.percent, &[56.31, 24.5, 10.73, 5.71, 2.74], 1e-4, "percent");
    check(&a.loadings[0], &[-0.49115363769227743, 0.4414710715524321, 0.2992087632563628, -0.5216859555968081, 0.44965461955553554], 1e-5, "loading 1");
    check(&a.loadings[1], &[0.3176210607298186, 0.5296116582246759, -0.7398086497911049, -0.04888384766499964, 0.26252977809212574], 1e-5, "loading 2");
    check(&a.loadings[2], &[-0.20967772785737068, -0.2919275815810521, -0.0703865115165766, 0.5542399911371186, 0.7474471946389669], 1e-5, "loading 3");
    check(&a.loadings[3], &[0.776678844174528, -0.10338100353368934, 0.415395088024756, -0.2402208033615036, 0.39474450926814014], 1e-5, "loading 4");
    check(&a.loadings[4], &[0.10339337219956286, 0.6547560153793639, 0.43087113795924104, 0.6004715905246394, -0.11995124991536828], 1e-5, "loading 5");
    check(&(0..5).map(|k| a.scores[k][0]).collect::<Vec<_>>(), &[1.7362193884095765, 1.9230476706365451, -0.015153143164416606, 0.4230538850935773, -0.023470260509795088], 1e-5, "scores of row 1");
    check(&(0..5).map(|k| a.scores[k][11]).collect::<Vec<_>>(), &[-2.505627987496701, 0.7890187128494113, -0.29573122591667783, -0.9307716116216245, 0.07864119636028423], 1e-5, "scores of row 12");
    for r in [3, 7, 8] { assert!(a.scores[0][r].is_nan()); }
}

#[test]
fn cov_listwise() {
    let a = pca(&data(), &PcaOptions { correlation: false, pairwise: false, components: 5, standardize_scores: false }).unwrap();
    check(&a.count.iter().map(|&n| n as f64).collect::<Vec<_>>(), &[9.0, 9.0, 9.0, 9.0, 9.0], 0.0, "N");
    check(&a.missing.iter().map(|&n| n as f64).collect::<Vec<_>>(), &[0.0, 1.0, 0.0, 2.0, 0.0], 0.0, "missing");
    check(&a.mean, &[24.747777777777777, 13.88111111111111, 16.645555555555553, 29.747777777777774, 18.26], 1e-12, "mean");
    check(&a.sd, &[2.428794854335056, 3.524799442679131, 3.7142297691146915, 9.278329291658304, 3.407099206069585], 1e-12, "sd");
    check(&a.eigenvalues, &[100.617729, 15.355785, 9.242176, 2.697821, 1.900967], 1e-5, "eigenvalues");
    check(&a.percent, &[77.51, 11.83, 7.12, 2.08, 1.46], 1e-4, "percent");
    check(&a.loadings[0], &[0.15704637648671999, -0.26025693658955396, -0.16047389090212755, 0.91923621569728, -0.19197831304261453], 1e-5, "loading 1");
    check(&a.loadings[1], &[0.20102939415213286, 0.4947691902482276, -0.8122730901684097, 0.012841278145206044, 0.2341754889645821], 1e-5, "loading 2");
    check(&a.loadings[2], &[-0.34129089786719813, 0.1367213974360226, 0.24585922974633068, 0.31528933100467976, 0.8396270954532766], 1e-5, "loading 3");
    check(&a.loadings[3], &[-0.4543848704602234, 0.7136852129448615, 0.19825657505180422, 0.22192750202030462, -0.4423011650634095], 1e-5, "loading 4");
    check(&a.loadings[4], &[0.7822905667647189, 0.3992874298611501, 0.4633660830534161, 0.07861744671375688, 0.08776210830281976], 1e-5, "loading 5");
    check(&(0..5).map(|k| a.scores[k][0]).collect::<Vec<_>>(), &[-11.645088446779702, 6.300460796991797, 0.932055747318234, -0.7764180328249287, 0.9456497582652056], 1e-5, "scores of row 1");
    check(&(0..5).map(|k| a.scores[k][11]).collect::<Vec<_>>(), &[14.449357386868213, 3.5898916591699868, -2.7435147788499727, 1.8356454040831702, -1.3817345015068718], 1e-5, "scores of row 12");
    for r in [3, 7, 8] { assert!(a.scores[0][r].is_nan()); }
    let t = a.tests.as_ref().unwrap();
    check(&[t[0].chi_square, t[0].df, t[0].p], &[27.9507, 14.0, 0.014444], 1e-5, "test 1");
    check(&[t[1].chi_square, t[1].df, t[1].p], &[7.48536, 9.0, 0.58672], 1e-5, "test 2");
    check(&[t[2].chi_square, t[2].df, t[2].p], &[4.00662, 5.0, 0.548463], 1e-5, "test 3");
    check(&[t[3].chi_square, t[3].df, t[3].p], &[0.167663, 2.0, 0.919586], 1e-5, "test 4");
}

#[test]
fn corr_pairwise() {
    let a = pca(&data(), &PcaOptions { correlation: true, pairwise: true, components: 5, standardize_scores: false }).unwrap();
    check(&a.count.iter().map(|&n| n as f64).collect::<Vec<_>>(), &[12.0, 11.0, 12.0, 10.0, 12.0], 0.0, "N");
    check(&a.missing.iter().map(|&n| n as f64).collect::<Vec<_>>(), &[0.0, 1.0, 0.0, 2.0, 0.0], 0.0, "missing");
    check(&a.mean, &[25.028333333333332, 13.67090909090909, 16.64916666666667, 28.844, 17.98916666666667], 1e-12, "mean");
    check(&a.sd, &[3.0619685686093363, 3.280263570341427, 3.6571063035071205, 9.202731720044387, 3.2083540337781637], 1e-12, "sd");
    check(&a.eigenvalues, &[2.567947, 1.145062, 0.589825, 0.514819, 0.182347], 1e-5, "eigenvalues");
    check(&a.percent, &[51.36, 22.9, 11.8, 10.3, 3.65], 1e-4, "percent");
    check(&a.loadings[0], &[-0.47929562213792437, 0.49052656261583194, 0.2239851738577825, -0.5751701148172398, 0.3855766835283719], 1e-5, "loading 1");
    check(&a.loadings[1], &[0.19047010326701438, 0.26658839829357034, -0.7950792931875538, 0.09516437807727775, 0.5014423439900819], 1e-5, "loading 2");
    check(&a.loadings[2], &[0.4788316196952651, 0.6554626155033068, -0.03296263033921642, -0.21594578055361113, -0.541636339733391], 1e-5, "loading 3");
    check(&a.loadings[3], &[0.6518499587983627, 0.021522549931633685, 0.5172287532239692, 0.046756120873004174, 0.5521926231473043], 1e-5, "loading 4");
    check(&a.loadings[4], &[-0.2825044381163856, 0.5081533791932996, 0.22151171814551693, 0.7818595559231136, 0.03999473959045178], 1e-5, "loading 5");
    check(&(0..5).map(|k| a.scores[k][0]).collect::<Vec<_>>(), &[2.005463839447119, 1.8168077103165214, 0.6218509155660064, 0.4844551625412347, 0.07330245981334883], 1e-5, "scores of row 1");
    check(&(0..5).map(|k| a.scores[k][11]).collect::<Vec<_>>(), &[-2.301021867481484, 0.7158593389491771, 0.5550540885734452, -1.2895869169583138, 0.34986871592247404], 1e-5, "scores of row 12");
    for r in [3, 7, 8] { assert!(a.scores[0][r].is_nan()); }
}

#[test]
fn cov_pairwise_3() {
    let a = pca(&data(), &PcaOptions { correlation: false, pairwise: true, components: 3, standardize_scores: false }).unwrap();
    check(&a.count.iter().map(|&n| n as f64).collect::<Vec<_>>(), &[12.0, 11.0, 12.0, 10.0, 12.0], 0.0, "N");
    check(&a.missing.iter().map(|&n| n as f64).collect::<Vec<_>>(), &[0.0, 1.0, 0.0, 2.0, 0.0], 0.0, "missing");
    check(&a.mean, &[25.028333333333332, 13.67090909090909, 16.64916666666667, 28.844, 17.98916666666667], 1e-12, "mean");
    check(&a.sd, &[3.0619685686093363, 3.280263570341427, 3.6571063035071205, 9.202731720044387, 3.2083540337781637], 1e-12, "sd");
    check(&a.eigenvalues, &[98.41635, 14.15144, 7.499291, 5.4294, 2.997533], 1e-5, "eigenvalues");
    check(&a.percent, &[76.59, 11.01, 5.84, 4.23, 2.33], 1e-4, "percent");
    check(&a.loadings[0], &[0.18975976795607785, -0.2602439212167018, -0.1373777807999714, 0.9240776786739442, -0.15320613908737862], 1e-5, "loading 1");
    check(&a.loadings[1], &[0.1037062413287731, 0.29399057413606366, -0.8414267863466759, 0.00956925863250723, 0.4412753679236314], 1e-5, "loading 2");
    check(&a.loadings[2], &[-0.5974864035613908, -0.21938575490473367, 0.2231036863976608, 0.21136138981611058, 0.7074114758151244], 1e-5, "loading 3");
    check(&(0..3).map(|k| a.scores[k][0]).collect::<Vec<_>>(), &[-10.874752182400252, 6.351984140864979, -0.29536542283269895], 1e-5, "scores of row 1");
    check(&(0..3).map(|k| a.scores[k][11]).collect::<Vec<_>>(), &[14.919858248889607, 2.947293012643512, -2.687589515687684], 1e-5, "scores of row 12");
    for r in [3, 7, 8] { assert!(a.scores[0][r].is_nan()); }
    let t = a.tests.as_ref().unwrap();
    check(&[t[0].chi_square, t[0].df, t[0].p], &[35.6046, 14.0, 0.00119548], 1e-5, "test 1");
    check(&[t[1].chi_square, t[1].df, t[1].p], &[5.23354, 9.0, 0.813493], 1e-5, "test 2");
    check(&[t[2].chi_square, t[2].df, t[2].p], &[1.73092, 5.0, 0.884982], 1e-5, "test 3");
    check(&[t[3].chi_square, t[3].df, t[3].p], &[0.739102, 2.0, 0.691045], 1e-5, "test 4");
}

fn check(got: &[f64], want: &[f64], tol: f64, what: &str) {
    assert_eq!(got.len(), want.len(), "{what}: length");
    for (g, w) in got.iter().zip(want) {
        assert!((g - w).abs() <= tol * w.abs().max(1e-3), "{what}: got {g}, Origin {w}");
    }
}
